<?php
$adminPage='support';$adminTitle='Support operations';$adminPermission='support.view';require __DIR__.'/../includes/admin_header.php';$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();requirePermission('support.manage');$id=(int)($_POST['case_id']??0);$action=$_POST['action']??'';if($action==='reply'){$body=trim($_POST['body']??'');if(strlen($body)<2)throw new InvalidArgumentException('Enter a reply.');$internal=isset($_POST['internal'])?1:0;$pdo->beginTransaction();$pdo->prepare('INSERT INTO support_messages(case_id,author_user_id,body,is_internal) VALUES(?,?,?,?)')->execute([$id,$_SESSION['user_id'],substr($body,0,5000),$internal]);$pdo->prepare("UPDATE support_cases SET assigned_to=?,status=IF(status='open','in_progress',status) WHERE case_id=?")->execute([$_SESSION['user_id'],$id]);audit($pdo,$internal?'support.internal_note':'support.reply','support_case',$id);$pdo->commit();$notice=$internal?'Internal note added.':'Customer reply recorded.';}elseif($action==='status'){$status=$_POST['status']??'';if(!in_array($status,['open','in_progress','waiting_customer','resolved','closed'],true))throw new InvalidArgumentException('Invalid case status.');$pdo->prepare("UPDATE support_cases SET status=?,assigned_to=?,closed_at=IF(? IN ('resolved','closed'),NOW(),NULL) WHERE case_id=?")->execute([$status,$_SESSION['user_id'],$status,$id]);audit($pdo,'support.status_changed','support_case',$id,['status'=>$status]);$notice='Case status updated.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}$selected=(int)($_GET['case']??0);$cases=$pdo->query("SELECT sc.*,u.full_name,u.email,a.full_name assignee FROM support_cases sc JOIN users u ON u.user_id=sc.user_id LEFT JOIN users a ON a.user_id=sc.assigned_to ORDER BY FIELD(sc.status,'open','in_progress','waiting_customer','resolved','closed'),sc.updated_at DESC LIMIT 100")->fetchAll();$messages=[];if($selected){$stmt=$pdo->prepare('SELECT sm.*,u.full_name author,u.role FROM support_messages sm JOIN users u ON u.user_id=sm.author_user_id WHERE sm.case_id=? ORDER BY sm.created_at');$stmt->execute([$selected]);$messages=$stmt->fetchAll();}
?>
<?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="app-grid"><section class="panel span-5"><h2>Case queue</h2><?php foreach($cases as $case):?><a class="note" style="display:block;color:inherit" href="support.php?case=<?=$case['case_id']?>"><strong><?=e($case['reference'])?> · <?=e($case['subject'])?></strong><br><span class="muted"><?=e($case['full_name'])?> · <?=e($case['priority'])?> · <?=e(str_replace('_',' ',$case['status']))?></span></a><?php endforeach;if(!$cases):?><div class="empty">No support cases.</div><?php endif?></section><section class="panel span-7"><?php if(!$selected):?><div class="empty">Select a case to review its customer-visible thread and internal notes.</div><?php else:?><h2>Case thread</h2><?php foreach($messages as $message):?><div class="note <?=$message['is_internal']?'risk-flag':''?>"><strong><?=e($message['author'])?><?=$message['is_internal']?' · internal':''?></strong><small> · <?=e(formatDate($message['created_at']))?></small><p><?=nl2br(e($message['body']))?></p></div><?php endforeach?><?php if(can('support.manage')):?><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="case_id" value="<?=$selected?>"><input type="hidden" name="action" value="reply"><div class="field full"><label>Reply or note</label><textarea name="body" maxlength="5000" required></textarea></div><label><input type="checkbox" name="internal"> Internal note—not visible to customer</label><button class="button button-primary">Add to case</button></form><form method="post" class="compact-form" style="margin-top:16px"><?=csrfField()?><input type="hidden" name="case_id" value="<?=$selected?>"><input type="hidden" name="action" value="status"><select name="status"><?php foreach(['open','in_progress','waiting_customer','resolved','closed'] as $s):?><option><?=$s?></option><?php endforeach?></select><button class="button button-secondary">Update status</button></form><?php endif?><?php endif?></section></div><?php require __DIR__.'/../includes/admin_footer.php';?>
